            parts = listOf(
                StoryPart(1, "An Empty Patch", listOf(
                    "A wooden bench had stood beneath the oldest tree in Riverside Park for as long as most residents could remember. One Monday it was gone, leaving four pale marks on the ground. Tobi, who visited the park with his grandfather, wondered whether it had been stolen. His teacher suggested checking the council's public notices before assuming what happened.",
